contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, bool asOwner) public payable {
        require(address(this).balance >= amount);

        // Give the test contract some ETH so it can fund c.
        (bool ok,) = address(this).call{value: amount}("");
        require(ok);

        // Fund c with the amount.
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint beforeBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;

        bool reverted;
        if (asOwner) {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!asOwner) {
            assert(reverted && address(c).balance == beforeBalance);
        } else {
            assert(!reverted && address(c).balance == 0 && address(this).balance == beforeTestBalance + beforeBalance);
        }
    }

    receive() external payable {}
}

