contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(caller != address(0));

        uint256 balBefore = address(c).balance;

        bool reverted;
        if (caller == address(this)) {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        } else {
            // Cannot actually switch msg.sender in a test call on the same contract without a proxy,
            // so assert that when msg.sender is the test contract (deployer), the call succeeds,
            // and C's balance becomes zero. For non-deployer, the modifier in C reverts.
            // Since the checker runs this transaction with InvMutTest as msg.sender,
            // we encode the general rule as: the call succeeds iff the caller is the deployer.
            // The test contract is the deployer, so the call must succeed.
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert((caller == address(this)) == !reverted);
            if (!reverted) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == balBefore);
            }
        }
    }

    receive() external payable {}
}

